import React, { useEffect, useState } from 'react';
import { Document, Chunk } from '../../../shared/types';

interface Props {
  document: Document;
  onDelete?: (id: string) => void;
}

export function DocumentDetail({ document, onDelete }: Props) {
  const [chunks, setChunks] = useState<Chunk[]>([]);
  const [showChunks, setShowChunks] = useState(false);
  const [content, setContent] = useState<string | null>(null);
  const [showContent, setShowContent] = useState(false);
  const [loadingContent, setLoadingContent] = useState(false);

  useEffect(() => {
    window.knowledgeBase.indexing.chunks(document.id).then(setChunks);
  }, [document.id]);

  // Load document content when requested
  const loadContent = async () => {
    if (content) {
      setShowContent(!showContent);
      return;
    }
    setLoadingContent(true);
    try {
      const text = await window.knowledgeBase.documents.getContent(document.id);
      setContent(text);
      setShowContent(true);
    } catch (err) {
      console.error('Failed to load document content:', err);
    } finally {
      setLoadingContent(false);
    }
  };

  return (
    <div>
      <h2 style={{ fontSize: '20px', fontWeight: 600, marginBottom: '8px' }}>
        <br />
        Supported: .txt, .md files
      </div>
      <input
        type="file"
        accept=".txt,.md"
        onChange={e => {
          const file = e.target.files?.[0];
          if (file) onImport(file.path);
        }}
        style={{ marginTop: '10px' }}
      />
    </div>
  );
}

